@startuml

class Customer {
  +vatNumber : string
  +name : string
  +phoneNumber : string
  +address : string
}

class Package {
  +weight : float
  +deliveryType : string
  +identifierCode : string
}

class DeliveryCenter {
  +name : string
  +address : string
}

class Courier {
  +vatNumber : string
  +name : string
  +phoneNumber : string
}

Customer "1" -- "*" Package : sender
Customer "1" -- "*" Package : recipient
Customer "*" -- "1" DeliveryCenter : associated
Courier "*" -- "1" DeliveryCenter : works for
Courier "1" -- "*" Package : assigned to
Package "*" -- "1" DeliveryCenter : delivered to
Package "*" -- "1" DeliveryCenter : routed through

@enduml

